<?= view('layout/header', ['title' => $item ? 'Edit customer' : 'Add customer']) ?><h1><?= $item ? 'Edit customer' : 'Add customer' ?></h1><div class="panel"><form method="post" action="<?= $item ? site_url('customers/' . $item['id']) : site_url('customers') ?>"><?= csrf_field() ?><label for="full_name">Full name</label><input id="full_name" name="full_name" required maxlength="100" value="<?= esc(old('full_name', $item['full_name'] ?? ''), 'attr') ?>"><label for="email">Email</label><input id="email" name="email" type="email" required maxlength="100" value="<?= esc(old('email', $item['email'] ?? ''), 'attr') ?>"><label for="phone">Phone (optional)</label><input id="phone" name="phone" maxlength="20" value="<?= esc(old('phone', $item['phone'] ?? ''), 'attr') ?>"><p><button>Save customer</button> <a href="<?= site_url('customers') ?>">Cancel</a></p></form></div><?= view('layout/footer') ?>
